#!/usr/bin/env python3
import hashlib,json,re,subprocess,sys
from pathlib import Path
assert sys.flags.isolated and sys.flags.no_site
root=Path(__file__).resolve().parents[2];repo=root.parents[1];p=root/'research/nine-sharing-sign14-positive74-object-predecessor-retry02-check';old=root/'research/nine-sharing-sign14-positive74-object-predecessor-retry01-check';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest()
assert sha(p/'run.py')=='319241b41a007ca8f85c5a1c842e6d3c0790c8f5dd623a9b950cb64c5dc53a39' and sha(p/'source-manifest.json')=='f4187987da98de8b9318d6e44a3bf2bbe717da1a613d2c9d4619092dbd93ae66'
e,=json.loads((p/'source-manifest.json').read_text())['rows'];n='Sign14Positive74ObjectPredecessor';q=p/'src/DiophantineConsistency'/(n+'.lean');s=q.read_text();assert e['module']=='DiophantineConsistency.'+n and sha(q)==sha(repo/e['source'])==e['source_sha256'] and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==e['imports'] and not re.search(r'(?m)^\s*(axiom|opaque|partial)\b|\b(sorry|admit|native_decide)\b',s)
previous=(old/'src/DiophantineConsistency'/(n+'.lean')).read_text();needle='  have hv0 : (fun i : Fin 2 => (Rew.embSubsts ![x]) (![.bvar 0, zeroTerm 1] i)) = ![x, zero] := by\n    apply funext\n    simp [Fin.forall_fin_two, zero, zeroTerm, Rew.func, funext_iff]';replacement='  have hv0 : (fun i : Fin 2 => (Rew.embSubsts ![x]) (![.bvar 0, .func (Code.zero 0) Fin.elim0] i)) = ![x, .func (Code.zero 0) Fin.elim0] := by\n    apply funext\n    simp [Fin.forall_fin_two, Rew.func, funext_iff]';assert previous.count(needle)==1 and s==previous.replace(needle,replacement)
for f in ('nine-sharing-sign14-positive74-object-predecessor-failure-independent','nine-sharing-sign14-positive74-object-predecessor-retry01-failure-independent','nine-sharing-sign14-positive74-object-guard-terminal-independent'):
 subprocess.run([sys.executable,'-I','-S','-B',str(root/'reviews'/f/'check.py')],capture_output=True,check=True,timeout=180)
x=subprocess.run([sys.executable,'-I','-S','-B',str(p/'framework-survey.py')],capture_output=True,text=True,check=True,timeout=180);v=json.loads(x.stdout);assert not x.stderr and v['status']=='PASS' and all(k in v['observed'] for k in ('IPRAPredReconstruct','IPRANativeAtomStability','IPRATheoryInstantiation','IntProver'))
r=(p/'run.py').read_text();assert "'-M3600'" in r and "LEAN_NUM_THREADS='1'" in r and "'-j1'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r and 'direct producer binding' in r
x=subprocess.run([sys.executable,'-I','-S','-B',str(p/'run.py'),'--preflight'],capture_output=True,text=True,check=True,timeout=180);assert not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','scope':'open predecessor only; historical direct object pins not source-authenticated'},indent=2))
